import unittest

from checkov.common.models.enums import CheckResult
from checkov.terraform.checks.resource.azure.PostgreSQLFlexiServerGeoBackupEnabled import check


class TestPostgreSQLFlexiServerGeoBackupEnabledUnknown(unittest.TestCase):
    def test_replica_returns_unknown(self):
        # Given a flexible server configured as a replica
        conf = {
            "create_mode": ["Replica"],
        }
        # When
        result = check.scan_resource_conf(conf)
        # Then
        self.assertEqual(CheckResult.UNKNOWN, result)
        self.assertIn("create_mode", check.get_evaluated_keys())

    def test_unresolved_variable_returns_unknown(self):
        # Given a flexible server with unresolved variable create_mode
        for val in ["var.create_mode", "${var.create_mode}", "${{var.create_mode}}", ["var.create_mode"]]:
            conf = {"create_mode": val if isinstance(val, list) else [val]}
            result = check.scan_resource_conf(conf)
            self.assertEqual(CheckResult.UNKNOWN, result)


if __name__ == "__main__":
    unittest.main()

